func:
// Persistent virtual-estimator state (context survives across ticks; msg does not).
// Instead of independent random draws each second, we random-walk a single
// "load" scalar (0-1, how hard the engine is working) with mean reversion, plus
// occasional FAULT/STOPPED episodes. Four metrics (engineRpm, lubOilPressure,
// fuelPressure, coolantPressure) are derived FROM load (+ a fault-severity
// ramp) the same tick they're computed; the two temperatures additionally
// integrate load through a slow first-order lag (thermal mass), so they trend
// over many ticks instead of tracking load instantaneously the way the
// pressures/RPM do.
//
// FAULT episodes carry a faultType so each failure mode has its own metric
// signature instead of one generic ramp applied evenly to all 6 metrics --
// this is what lets the dashboard/model later tell "why" a fault is
// happening, not just "that" it is happening. Engineering judgment, not
// derived from data/train.csv, which carries no fault-type supervision at
// all (see docs/plan/2026-08-26-pump-to-engine-migration.md §4.2).
//   OIL_PRESSURE_LOSS -- oil pump/pickup failure or leak: lubOilPressure
//                        collapses, lubOilTemperature climbs moderately from
//                        increased friction as lubrication breaks down.
//   COOLANT_OVERHEAT  -- cooling system can't keep up with load (fan/pump
//                        failure, blocked radiator): both temperatures climb
//                        hard; coolant pressure drifts down as coolant
//                        boils/vents rather than building further.
//   COOLANT_LOSS      -- coolant leak: coolantPressure collapses (loss of
//                        the sealed system's charge) while both temperatures
//                        climb hard from reduced heat rejection -- pressure
//                        direction is what distinguishes this from
//                        COOLANT_OVERHEAT, which still has coolant to
//                        pressurize even as it fails to reject heat fast enough.
//   FUEL_STARVATION   -- fuel delivery restricted (clogged filter/pump wear):
//                        fuelPressure collapses, engineRpm sags and becomes
//                        unstable as the engine struggles for fuel -- the
//                        most immediately unstable-looking fault, by design.
//   OVERSPEED         -- governor/throttle fault: engineRpm spikes well past
//                        normal operating range, dragging oil/fuel pressure
//                        and both temperatures up as everything works harder
//                        than the engine was designed for at steady state.
//   OIL_DEGRADATION   -- oil breaking down / wrong viscosity: a slower,
//                        quieter fault than OIL_PRESSURE_LOSS -- oil pressure
//                        sags gradually rather than collapsing, while
//                        lubOilTemperature is the dominant, fastest-rising
//                        signal (degraded oil is a worse lubricant/coolant).
//   THERMOSTAT_STUCK  -- thermostat stuck OPEN: the engine runs COLD, not
//                        hot -- both temperatures fall (opposite direction
//                        from every other fault here) and coolant pressure
//                        sags slightly since a fully-open loop never builds
//                        the same back-pressure a regulated one does. This is
//                        the one deliberately "backwards" fault signature, to
//                        keep Tier 1/2 from learning "any deviation = high
//                        temp".
// Each profile is a per-metric delta APPLIED AT fault=1 (full severity); it
// scales linearly with faultSeverity like the original single-fault-term
// design did.

function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }
function jitter(scale) { return (Math.random() - 0.5) * 2 * scale; }
function randInt(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }
function step(current, target, speed, noise) { return current + speed * (target - current) + jitter(noise); }

const FAULT_PROFILES = {
    OIL_PRESSURE_LOSS: { engineRpm: 0,    lubOilPressure: -3.5, fuelPressure: 0,  coolantPressure: 0,    lubOilTemperature: 6,  coolantTemperature: 1   },
    COOLANT_OVERHEAT:  { engineRpm: 0,    lubOilPressure: 0,    fuelPressure: 0,  coolantPressure: -1.0, lubOilTemperature: 8,  coolantTemperature: 18  },
    COOLANT_LOSS:      { engineRpm: 0,    lubOilPressure: 0,    fuelPressure: 0,  coolantPressure: -2.5, lubOilTemperature: 7,  coolantTemperature: 20  },
    FUEL_STARVATION:   { engineRpm: -300, lubOilPressure: 0,    fuelPressure: -9, coolantPressure: 0,    lubOilTemperature: 0,  coolantTemperature: 0   },
    OVERSPEED:         { engineRpm: 700,  lubOilPressure: 0.5,  fuelPressure: 3,  coolantPressure: 0,    lubOilTemperature: 5,  coolantTemperature: 5   },
    OIL_DEGRADATION:   { engineRpm: 0,    lubOilPressure: -1.5, fuelPressure: 0,  coolantPressure: 0,    lubOilTemperature: 10, coolantTemperature: 2   },
    THERMOSTAT_STUCK:  { engineRpm: 0,    lubOilPressure: 0,    fuelPressure: 0,  coolantPressure: -1.0, lubOilTemperature: -4, coolantTemperature: -12 }
};
const FAULT_TYPES = Object.keys(FAULT_PROFILES);

let state = context.get('state');
if (!state) {
    state = { load: 0.5, regime: 'RUNNING', regimeTicksLeft: 0, regimeTotalTicks: 0, faultSeverity: 0, faultType: null, lubOilTemp: 79, coolantTemp: 78 };
}

// Regime transitions: mostly RUNNING, with rare FAULT / STOPPED episodes.
if (state.regimeTicksLeft > 0) {
    state.regimeTicksLeft--;
    if (state.regimeTicksLeft === 0) {
        state.regime = 'RUNNING';
        state.faultSeverity = 0;
        state.faultType = null;
    }
} else if (state.regime === 'RUNNING') {
    if (Math.random() < 0.003) {
        state.regime = 'FAULT';
        state.faultType = FAULT_TYPES[randInt(0, FAULT_TYPES.length - 1)];
        state.regimeTotalTicks = randInt(15, 40);
        state.regimeTicksLeft = state.regimeTotalTicks;
    } else if (Math.random() < 0.002) {
        state.regime = 'STOPPED';
        state.regimeTotalTicks = randInt(20, 60);
        state.regimeTicksLeft = state.regimeTotalTicks;
    }
}

// Fault severity ramps 0 -> ~1 across the episode, then resets on recovery.
if (state.regime === 'FAULT') {
    state.faultSeverity = 1 - (state.regimeTicksLeft / state.regimeTotalTicks);
}

// "load" = how hard the engine is working (0-1). Random-walks with mean
// reversion toward a regime-specific target, so it drifts smoothly instead
// of teleporting -- this is what gives RPM/pressures real momentum/trend.
const loadTarget = state.regime === 'STOPPED' ? 0.02 : 0.5;
const loadSpeed  = state.regime === 'STOPPED' ? 0.35 : 0.06;
const loadNoise  = state.regime === 'STOPPED' ? 0.02 : 0.05;
state.load = clamp(step(state.load, loadTarget, loadSpeed, loadNoise), 0.02, 1);

// Noise gets louder as fault severity rises (heteroscedastic measurement noise).
const noiseScale = 1 + state.faultSeverity * 2;
const load = state.load;
const fault = state.faultSeverity;
const profile = state.faultType ? FAULT_PROFILES[state.faultType] : null;
function delta(metric) { return profile ? fault * profile[metric] : 0; }

function round1(v) { return Math.round(v * 10) / 10; }
function round2(v) { return Math.round(v * 100) / 100; }

// Oil pressure is pump-driven off the crank: it rises fast at low load then
// plateaus (saturating curve), unlike RPM/fuel pressure which track load
// roughly linearly.
const oilPressureLoad = 1 - Math.pow(1 - load, 2);

// Both temperatures have real thermal mass -- they integrate load over many
// ticks (first-order lag toward a load-dependent target) rather than
// tracking it instantaneously like the pressures/RPM do. Lag speed is much
// slower than load's own random walk on purpose.
const lubOilTempTarget = 65 + load * 30 + delta('lubOilTemperature');
const coolantTempTarget = 62 + load * 30 + delta('coolantTemperature');
state.lubOilTemp = step(state.lubOilTemp, lubOilTempTarget, 0.02, 0.3 * noiseScale);
state.coolantTemp = step(state.coolantTemp, coolantTempTarget, 0.015, 0.35 * noiseScale);

// engineRpm's base offset is deliberately small (unlike the old pump
// simulator's rpm formula, whose 1000 base never actually dropped near zero
// even while STOPPED) -- STOPPED needs load pulled down near its 0.02 floor
// to land engineRpm under validator.js's 200 RPM STOPPED-consistency
// threshold, or that rule could never actually pass.
//
// NOTE: state.faultType (which FAULT_PROFILES entry is driving this
// episode's metric deltas) is intentionally NOT included below. Real
// sensors report readings and operational status, never a diagnosis --
// faultType is a HITL reviewer's conclusion (fault_events.faultType, set
// on review/confirm), or later an auto-classification once a reviewed
// signature repeats. Leaking the ground-truth label into the live stream
// would make Tier 1/Tier 2 trivial and defeat the point of building them.
msg.payload = {
    engineRpm:           round1(clamp(100  + load * 1465 + delta('engineRpm')          + jitter(25   * noiseScale), 0,  2500)),
    lubOilPressure:      round2(clamp(0.858 + oilPressureLoad * 4.75 + delta('lubOilPressure') + jitter(0.15 * noiseScale), 0,  8.5)),
    fuelPressure:        round2(clamp(1.4  + load * 14.7  + delta('fuelPressure')      + jitter(0.4  * noiseScale), 0,  23)),
    coolantPressure:     round2(clamp(0.72 + load * 5.2   + delta('coolantPressure')   + jitter(0.15 * noiseScale), 0,  9)),
    lubOilTemperature:   round1(clamp(state.lubOilTemp, 65, 95)),
    coolantTemperature:  round1(clamp(state.coolantTemp, 60, 108)),
    status:              state.regime,
    timestamp:           new Date().toISOString()
};

context.set('state', state);

// Tell the backend the body is JSON so Express parses it correctly.
msg.headers = { "Content-Type": "application/json" };

return msg;

// The message a Catch node receives is the ORIGINAL message that entered
// the failing node — msg.payload is still the reading object built by
// gen_reading, not a response body, since the request never succeeded.
const MAX_RETRIES = 3;
msg.retryCount = (msg.retryCount || 0) + 1;

if (msg.retryCount > MAX_RETRIES) {
    node.warn(`POST /api/data failed after ${MAX_RETRIES} retries -- dropping reading for ${msg.payload && msg.payload.timestamp}`);
    return null; // give up; this tick's reading is genuinely lost, same as before the retry queue existed
}

node.warn(`POST /api/data failed (attempt ${msg.retryCount}/${MAX_RETRIES}) -- retrying in 1s for ${msg.payload && msg.payload.timestamp}`);
msg.headers = { "Content-Type": "application/json" };
return msg;
